using System;
using System.Collections.Generic;
using UnityEngine;

[Serializable]
public class RecipeStep
{
    public string IngredientId;
    public float MinAmount;
    public float MaxAmount;
    public float MaxAllowedHeat;
}

[CreateAssetMenu(menuName = "Beans&Rats/Recipe")]
public class RecipeDefinition : ScriptableObject
{
    public string RecipeId;
    public List<RecipeStep> Steps = new();
}

public sealed class CauldronController : MonoBehaviour
{
    [SerializeField] private RecipeDefinition activeRecipe;

    private int _stepIndex;

    public event Action<int, int> OnStepChanged; // current, total
    public event Action OnRecipeCompleted;
    public event Action<string> OnRecipeFailed;

    public void StartRecipe(RecipeDefinition recipe)
    {
        activeRecipe = recipe;
        _stepIndex = 0;
        OnStepChanged?.Invoke(_stepIndex, activeRecipe.Steps.Count);
    }

    public void ApplyIngredient(string ingredientId, float amount, float currentHeat)
    {
        if (activeRecipe == null || _stepIndex >= activeRecipe.Steps.Count)
            return;

        var step = activeRecipe.Steps[_stepIndex];

        if (!string.Equals(step.IngredientId, ingredientId, StringComparison.OrdinalIgnoreCase))
        {
            OnRecipeFailed?.Invoke($"Wrong ingredient: {ingredientId}");
            return;
        }

        if (amount < step.MinAmount || amount > step.MaxAmount)
        {
            OnRecipeFailed?.Invoke($"Wrong amount: {amount:0.00}");
            return;
        }

        if (currentHeat > step.MaxAllowedHeat)
        {
            OnRecipeFailed?.Invoke($"Too hot: {currentHeat:0.0}");
            return;
        }

        _stepIndex++;
        OnStepChanged?.Invoke(_stepIndex, activeRecipe.Steps.Count);

        if (_stepIndex >= activeRecipe.Steps.Count)
            OnRecipeCompleted?.Invoke();
    }
}

using UnityEngine;

public sealed class PouringController : MonoBehaviour
{
    [Header("References")]
    [SerializeField] private Transform container;
    [SerializeField] private ParticleSystem pourVfx;

    [Header("Tuning")]
    [SerializeField, Range(0f, 90f)] private float startAngle = 35f;
    [SerializeField, Range(0f, 90f)] private float fullAngle = 75f;
    [SerializeField] private AnimationCurve flowCurve = AnimationCurve.Linear(0, 0, 1, 1);

    public float Flow01 { get; private set; }

    private ParticleSystem.EmissionModule _emission;

    private void Awake()
    {
        if (pourVfx != null)
            _emission = pourVfx.emission;
    }

    private void Update()
    {
        if (container == null) return;

        // 0° = upright, 90° = sideways
        float angle = Vector3.Angle(container.up, Vector3.up);

        float t = Mathf.InverseLerp(startAngle, fullAngle, angle);
        t = Mathf.Clamp01(t);

        Flow01 = flowCurve.Evaluate(t);

        if (pourVfx != null)
        {
            bool shouldPour = Flow01 > 0.01f;
            if (shouldPour && !pourVfx.isPlaying) pourVfx.Play();
            if (!shouldPour && pourVfx.isPlaying) pourVfx.Stop();

            _emission.rateOverTime = 60f * Flow01;
        }
    }
}

using System.Collections;
using UnityEngine;

public sealed class BookPageFlip : MonoBehaviour
{
    [SerializeField] private Renderer pageRenderer;
    [SerializeField] private string flipProperty = "_Flip";
    [SerializeField] private float flipDuration = 0.35f;
    [SerializeField] private AnimationCurve flipCurve = AnimationCurve.EaseInOut(0, 0, 1, 1);

    private MaterialPropertyBlock _mpb;
    private Coroutine _routine;

    private void Awake()
    {
        _mpb = new MaterialPropertyBlock();
        SetFlip(0f);
    }

    public void FlipForward()
    {
        StartFlip(1f);
    }

    public void FlipBackward()
    {
        StartFlip(0f);
    }

    private void StartFlip(float target)
    {
        if (_routine != null) StopCoroutine(_routine);
        _routine = StartCoroutine(FlipRoutine(target));
    }

    private IEnumerator FlipRoutine(float target)
    {
        float start = GetFlip();
        float time = 0f;

        while (time < flipDuration)
        {
            time += Time.deltaTime;
            float t = Mathf.Clamp01(time / flipDuration);
            float v = Mathf.Lerp(start, target, flipCurve.Evaluate(t));
            SetFlip(v);
            yield return null;
        }

        SetFlip(target);
        _routine = null;
    }

    private float GetFlip()
    {
        if (pageRenderer == null) return 0f;
        pageRenderer.GetPropertyBlock(_mpb);
        return _mpb.GetFloat(flipProperty);
    }

    private void SetFlip(float value)
    {
        if (pageRenderer == null) return;
        pageRenderer.GetPropertyBlock(_mpb);
        _mpb.SetFloat(flipProperty, value);
        pageRenderer.SetPropertyBlock(_mpb);
    }
}
